import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [items, setItems] = useState([
    { id: 1, text: 'Learn React' },
    { id: 2, text: 'Fix bugs' },
    { id: 3, text: 'Ship code' },
  ]);

  const deleteItem = (id) => {
    setItems(items.filter(item => item.id !== id));
  };

  return (
    <div>
      <h2>Todo List</h2>
      <ul id="todo-list">
        {items.map((item, index) => (
          <li key={index}>
            <span className="item-text">{item.text}</span>
            <button className="delete-btn" onClick={() => deleteItem(item.id)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;

