import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Disappearing List', () => {
  test('Renders all 3 items initially', async () => {
    const { container: root } = render(<App />);
    const items = root.querySelectorAll('#todo-list li');
if (items.length !== 3) throw new Error('Expected 3 items, found ' + items.length);
  });

  test('Deleting middle item removes correct one', async () => {
    const { container: root } = render(<App />);
    const buttons = root.querySelectorAll('.delete-btn');
buttons[1].click();
await tick();
const items = root.querySelectorAll('#todo-list li');
if (items.length !== 2) throw new Error('Expected 2 items after delete');
const texts = Array.from(items).map(li => li.querySelector('.item-text').textContent);
if (texts.includes('Fix bugs')) throw new Error('"Fix bugs" should have been deleted');
if (!texts.includes('Learn React')) throw new Error('"Learn React" should still exist');
if (!texts.includes('Ship code')) throw new Error('"Ship code" should still exist');
  });

  test('Uses stable keys (not array index)', async () => {
    const { container: root } = render(<App />);
    const buttons = root.querySelectorAll('.delete-btn');
buttons[0].click();
await tick();
const items = root.querySelectorAll('#todo-list li');
const text = items[0]?.querySelector('.item-text')?.textContent;
if (text !== 'Ship code') throw new Error('After deleting first item, "Ship code" should remain correctly positioned');
  });
});
